import { spawn } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const isWin = process.platform === "win32";
const npm = isWin ? "npm.cmd" : "npm";

function run(script) {
  return spawn(npm, ["run", script], {
    cwd: root,
    stdio: "inherit",
    shell: isWin,
    env: process.env,
  });
}

const children = [run("server"), run("dev")];

function shutdown(code = 0) {
  for (const child of children) {
    if (!child.killed) {
      child.kill();
    }
  }
  process.exit(code);
}

process.on("SIGINT", () => shutdown(0));
process.on("SIGTERM", () => shutdown(0));

for (const child of children) {
  child.on("exit", (code) => {
    if (code !== 0 && code !== null) {
      console.error(`进程退出，代码 ${code}`);
      shutdown(code);
    }
  });
}

$ErrorActionPreference = "Stop"

$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root

function Write-Step([string]$Message) {
  Write-Host $Message
}

function Test-NodeAvailable {
  $node = Get-Command node -ErrorAction SilentlyContinue
  if (-not $node) {
    Write-Host "未找到 Node.js，请先安装：https://nodejs.org/" -ForegroundColor Red
    if ($Host.Name -eq "ConsoleHost") {
      Read-Host "按 Enter 退出"
    }
    exit 1
  }
}

function Ensure-Dependencies {
  if (-not (Test-Path -LiteralPath (Join-Path $Root "node_modules"))) {
    Write-Step "首次运行，正在安装依赖..."
    & npm install
    if ($LASTEXITCODE -ne 0) {
      throw "npm install 失败，退出代码 $LASTEXITCODE"
    }
  }
}

function Start-NpmScript([string]$Name, [string]$Script) {
  $logsDir = Join-Path $Root "logs"
  if (-not (Test-Path -LiteralPath $logsDir)) {
    New-Item -ItemType Directory -Path $logsDir | Out-Null
  }

  $logFile = Join-Path $logsDir "$Name.log"
  $cmd = "npm run $Script >> `"$logFile`" 2>&1"

  Start-Process -FilePath "cmd.exe" `
    -ArgumentList "/c", $cmd `
    -WorkingDirectory $Root `
    -WindowStyle Minimized | Out-Null
}

function Wait-ForUrl([string]$Url, [int]$TimeoutSec) {
  $deadline = (Get-Date).AddSeconds($TimeoutSec)
  while ((Get-Date) -lt $deadline) {
    try {
      $response = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 2
      if ($response.StatusCode -ge 200 -and $response.StatusCode -lt 500) {
        return $true
      }
    } catch {
      # keep polling
    }
    Start-Sleep -Milliseconds 500
  }
  return $false
}

Test-NodeAvailable
Ensure-Dependencies

Write-Step "正在启动后端 http://127.0.0.1:8787 ..."
Start-NpmScript -Name "backend" -Script "server"

Write-Step "正在启动前端 http://127.0.0.1:5173 ..."
Start-NpmScript -Name "frontend" -Script "dev"

Write-Step "等待服务就绪（最多 60 秒）..."
$backendReady = Wait-ForUrl "http://127.0.0.1:8787/api/health" 60
$frontendReady = Wait-ForUrl "http://127.0.0.1:5173/" 60

if ($backendReady) {
  Write-Host "后端已就绪" -ForegroundColor Green
} else {
  Write-Host "后端未启动，请查看 logs\backend.log" -ForegroundColor Red
}

if ($frontendReady) {
  Write-Host "前端已就绪" -ForegroundColor Green
} else {
  Write-Host "前端未启动，请查看 logs\frontend.log" -ForegroundColor Red
}

if ($backendReady -and $frontendReady) {
  Start-Process "http://127.0.0.1:5173/"
  Write-Step "已在浏览器打开产品页面。"
} else {
  $entry = Join-Path $Root "experience-entry.html"
  if (Test-Path -LiteralPath $entry) {
    Start-Process $entry
  }
  Write-Step "已在浏览器打开体验入口页；服务启动后会自动检测并跳转。"
  Write-Step "也可查看 logs 目录排查启动错误。"
}

if ($Host.Name -eq "ConsoleHost") {
  Write-Step "本窗口可关闭，前后端在后台继续运行。"
}

@echo off
chcp 65001 >nul
cd /d "%~dp0"
powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0start-experience.ps1"
if errorlevel 1 (
  echo.
  echo 启动失败，请确认已安装 Node.js 并查看 logs 目录。
  pause
)

