if (-not $nodeCmd) {
  Write-Host "未检测到 Node.js，请先安装：https://nodejs.org/" -ForegroundColor Red
  exit 1
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "node_modules"))) {
  Write-Host "首次运行，正在安装依赖…" -ForegroundColor Yellow
