  echo.
  echo 启动失败，请确认已安装 Node.js 并查看 logs 目录。
  pause
)
```

### 3. 新建 `scripts/start-dev.mjs`（终端里 `npm start` 用）

```javascript
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const npmCmd = process.platform === "win32" ? "npm.cmd" : "npm";
const children = [];

function runNpmScript(script) {
  const child = spawn(npmCmd, ["run", script], {
    cwd: root,
    stdio: "inherit",
    shell: false,
  });
  children.push(child);
  child.on("exit", (code, signal) => {
    if (signal) return;
    if (code !== 0 && code !== null) {
      console.error(`[start-dev] npm run ${script} exited with code ${code}`);
      shutdown(code ?? 1);
    }
  });
  return child;
}

function shutdown(exitCode = 0) {
  for (const child of children) {
    if (!child.killed) child.kill("SIGTERM");
  }
  process.exit(exitCode);
}

process.on("SIGINT", () => {
  console.log("\n[start-dev] 正在停止服务…");
  shutdown(0);
});
process.on("SIGTERM", () => shutdown(0));

console.log("[start-dev] 启动后端 (npm run server) 与前端 (npm run dev)…");
runNpmScript("server");
runNpmScript("dev");
```

### 4. 更新 `package.json` 的 `scripts`

在现有 scripts 最前面加：

```json
"start": "node scripts/start-dev.mjs",
"start:experience": "powershell -NoProfile -ExecutionPolicy Bypass -File ./start-experience.ps1",
```

### 5. 更新 `experience-entry.html` 和 `体验入口.html`

把说明里的：

> 请先运行同目录的 start-experience.ps1

改为：

> 请双击同目录的 **启动体验.cmd**，或在项目根目录运行 `npm run start:experience`

把底部代码块从：

```text
powershell -ExecutionPolicy Bypass -File .\start-experience.ps1
```

改为：

```text
启动体验.cmd
```

并加一行：`或在终端执行：npm run start:experience`

### 6. `.gitignore` 追加

```text
logs/
```

---

## 使用方式

| 方式 | 说明 |
|------|------|
| **双击 `启动体验.cmd`** | 推荐：自动装依赖、启前后端、等健康检查、打开浏览器 |
| `npm run start:experience` | 同上，走 PowerShell 脚本 |
| `npm start` | 终端前台同时跑前后端（Ctrl+C 一起停） |

启动失败时看 `logs/server.log` 和 `logs/dev.log`。

---

## Completed / Verified / Remaining Risks

